/* AES-256 + CBC + PKCS7. Self-contained, public domain.
 * Adapted from the canonical FIPS-197 specification — no SIMD, no tables
 * other than the standard S-box / Rcon. ~5 KB compiled. */
#include "aes256.h"
#include <stdlib.h>
