static const uint8_t Rcon[11] = {
    0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36
};

typedef uint8_t state_t[4][4];

static void key_expansion(uint8_t *rk, const uint8_t *key) {
    memcpy(rk, key, Nk * 4);
    uint8_t t[4];
    for (int i = Nk; i < Nb * (Nr + 1); i++) {
        t[0] = rk[(i-1)*4 + 0];
        t[1] = rk[(i-1)*4 + 1];
        t[2] = rk[(i-1)*4 + 2];
        t[3] = rk[(i-1)*4 + 3];
        if (i % Nk == 0) {
            uint8_t tmp = t[0];
            t[0] = sbox[t[1]] ^ Rcon[i / Nk];
            t[1] = sbox[t[2]];
            t[2] = sbox[t[3]];
            t[3] = sbox[tmp];
        } else if (i % Nk == 4) {
            t[0] = sbox[t[0]];
            t[1] = sbox[t[1]];
            t[2] = sbox[t[2]];
            t[3] = sbox[t[3]];
        }
        rk[i*4 + 0] = rk[(i - Nk)*4 + 0] ^ t[0];
        rk[i*4 + 1] = rk[(i - Nk)*4 + 1] ^ t[1];
        rk[i*4 + 2] = rk[(i - Nk)*4 + 2] ^ t[2];
        rk[i*4 + 3] = rk[(i - Nk)*4 + 3] ^ t[3];
    }
}

static void add_round_key(state_t *s, const uint8_t *rk, int round) {
    for (int c = 0; c < 4; c++)
        for (int r = 0; r < 4; r++)
            (*s)[r][c] ^= rk[round * 16 + c * 4 + r];
}

static void inv_sub_bytes(state_t *s) {
    for (int r = 0; r < 4; r++)
        for (int c = 0; c < 4; c++)
            (*s)[r][c] = rsbox[(*s)[r][c]];
}

static void inv_shift_rows(state_t *s) {
    uint8_t t;
    /* row 1: shift right 1 */
    t = (*s)[1][3]; (*s)[1][3] = (*s)[1][2]; (*s)[1][2] = (*s)[1][1];
    (*s)[1][1] = (*s)[1][0]; (*s)[1][0] = t;
    /* row 2: shift right 2 */
    t = (*s)[2][0]; (*s)[2][0] = (*s)[2][2]; (*s)[2][2] = t;
    t = (*s)[2][1]; (*s)[2][1] = (*s)[2][3]; (*s)[2][3] = t;
    /* row 3: shift right 3 (== shift left 1) */
    t = (*s)[3][0]; (*s)[3][0] = (*s)[3][1]; (*s)[3][1] = (*s)[3][2];
    (*s)[3][2] = (*s)[3][3]; (*s)[3][3] = t;
}

static uint8_t xt(uint8_t b) { return (uint8_t)((b << 1) ^ ((b >> 7) * 0x1b)); }
static uint8_t mul(uint8_t b, uint8_t f) {
    uint8_t r = 0;
    while (f) {
        if (f & 1) r ^= b;
        b = xt(b);
        f >>= 1;
    }
    return r;
}

static void inv_mix_columns(state_t *s) {
    for (int c = 0; c < 4; c++) {
        uint8_t a = (*s)[0][c], b = (*s)[1][c], cc = (*s)[2][c], d = (*s)[3][c];
        (*s)[0][c] = mul(a, 0x0e) ^ mul(b, 0x0b) ^ mul(cc, 0x0d) ^ mul(d, 0x09);
        (*s)[1][c] = mul(a, 0x09) ^ mul(b, 0x0e) ^ mul(cc, 0x0b) ^ mul(d, 0x0d);
        (*s)[2][c] = mul(a, 0x0d) ^ mul(b, 0x09) ^ mul(cc, 0x0e) ^ mul(d, 0x0b);
        (*s)[3][c] = mul(a, 0x0b) ^ mul(b, 0x0d) ^ mul(cc, 0x09) ^ mul(d, 0x0e);
    }
}

static void aes256_decrypt_block(const uint8_t *rk, const uint8_t *in, uint8_t *out) {
    state_t s;
    for (int c = 0; c < 4; c++)
        for (int r = 0; r < 4; r++)
            s[r][c] = in[c*4 + r];
    add_round_key(&s, rk, Nr);
    for (int round = Nr - 1; round >= 1; round--) {
        inv_shift_rows(&s);
        inv_sub_bytes(&s);
        add_round_key(&s, rk, round);
        inv_mix_columns(&s);
    }
    inv_shift_rows(&s);
    inv_sub_bytes(&s);
    add_round_key(&s, rk, 0);
    for (int c = 0; c < 4; c++)
        for (int r = 0; r < 4; r++)
            out[c*4 + r] = s[r][c];
}

uint8_t *aes256_cbc_decrypt_pkcs7(const uint8_t key[32], const uint8_t iv[16],
                                  const uint8_t *ct, size_t ct_len,
                                  size_t *out_len) {
    if (ct_len == 0 || ct_len % 16) return NULL;
    uint8_t rk[(Nr + 1) * 16];
    key_expansion(rk, key);

    uint8_t *out = (uint8_t *)malloc(ct_len);
    if (!out) return NULL;

    uint8_t prev[16];
    memcpy(prev, iv, 16);

    for (size_t off = 0; off < ct_len; off += 16) {
        uint8_t blk[16];
        aes256_decrypt_block(rk, ct + off, blk);
        for (int i = 0; i < 16; i++) blk[i] ^= prev[i];
        memcpy(prev, ct + off, 16);
        memcpy(out + off, blk, 16);
    }

    /* PKCS7 strip */
    uint8_t pad = out[ct_len - 1];
    if (pad == 0 || pad > 16) { free(out); return NULL; }
    for (size_t i = 0; i < pad; i++) {
        if (out[ct_len - 1 - i] != pad) { free(out); return NULL; }
    }
    *out_len = ct_len - pad;
    return out;
}
